(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.LimitIdeaLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function fmt(x){return String(Number(x.toFixed(3))).replace('.','{,}');}
const formulas={smooth:String.raw`f(x)=x+2`,hole:String.raw`f(x)=\frac{x^2-1}{x-1},\quad x\ne1`,changed:String.raw`f(x)=\begin{cases}x+1,&x\ne1,\\4,&x=1,\end{cases}`,jump:String.raw`f(x)=\begin{cases}1,&x<1,\\3,&x\ge1.\end{cases}`};
let grid='';for(let x=-1;x<=3;x++){const p=core.point(x,0);grid+=`<line x1="${p.x}" x2="${p.x}" y1="30" y2="310" class="${x===0?'wave-axis':'wave-grid-line'}"/><text x="${p.x}" y="332" text-anchor="middle" class="wave-grid-label">${x}</text>`;}for(let y=0;y<=5;y++){const p=core.point(0,y);grid+=`<line x1="50" x2="610" y1="${p.y}" y2="${p.y}" class="${y===0?'wave-axis':'wave-grid-line'}"/><text x="42" y="${p.y+5}" text-anchor="end" class="wave-grid-label">${y}</text>`;}$('#limit-grid').innerHTML=grid;
function segment(x1,y1,x2,y2){const a=core.point(x1,y1),b=core.point(x2,y2);return `M${a.x} ${a.y}L${b.x} ${b.y}`;}
function circle(y,kind){const p=core.point(1,y);return `<circle cx="${p.x}" cy="${p.y}" r="5" class="limit-${kind}"/>`;}
function draw(){const kind=$('#limit-kind').value,index=Number($('#limit-step').value),d=core.distances[index],t=core.approach(kind,d);$('#step-output').value=String(d).replace('.',',');$('#limit-step').setAttribute('aria-valuetext',String(d));math($('#limit-formula'),formulas[kind]);const boundaryLeft=kind==='smooth'?3:kind==='jump'?1:2,boundaryRight=kind==='smooth'?3:kind==='jump'?3:2;$('#limit-left-curve').setAttribute('d',segment(-1,core.value(kind,-1),1,boundaryLeft));$('#limit-right-curve').setAttribute('d',segment(1,boundaryRight,3,core.value(kind,3)));$('#limit-special-points').innerHTML=kind==='hole'?circle(2,'hole'):kind==='changed'?circle(2,'hole')+circle(4,'filled'):kind==='jump'?circle(1,'hole')+circle(3,'filled'):circle(3,'filled');for(const [id,x,y]of [['limit-left-point',t.leftX,t.leftY],['limit-right-point',t.rightX,t.rightY]]){const p=core.point(x,y);$('#'+id).setAttribute('cx',p.x);$('#'+id).setAttribute('cy',p.y);}$('#limit-table').innerHTML=core.distances.map((distance,i)=>{const v=core.approach(kind,distance);return `<tr ${i===index?'class="limit-selected"':''}>${[distance,v.leftX,v.leftY,v.rightX,v.rightY].map(n=>`<td><span data-tex="${fmt(n)}"></span></td>`).join('')}</tr>`;}).join('');math($('#limit-values'),String.raw`\begin{aligned}f(${fmt(t.leftX)})&=${fmt(t.leftY)}\\f(${fmt(t.rightX)})&=${fmt(t.rightY)}\\f(1)&`+(t.at===null?String.raw`\text{ tidak terdefinisi}`:'='+fmt(t.at))+String.raw`\end{aligned}`);math($('#limit-conclusion'),String.raw`\begin{aligned}\lim_{x\to1^-}f(x)&=${t.leftLimit}\\\lim_{x\to1^+}f(x)&=${t.rightLimit}\\\lim_{x\to1}f(x)&`+(t.limit===null?String.raw`\text{ tidak ada}`:'='+t.limit)+String.raw`\end{aligned}`);$('#limit-note').textContent=kind==='smooth'?'Kedua sisi mendekati tiga, dan nilai fungsi di titik juga tiga. Pada contoh ini, limit sama dengan nilai fungsi.':kind==='hole'?'Kedua sisi mendekati dua meskipun fungsi tidak terdefinisi di masukan satu. Lubang di titik tidak menghalangi adanya limit.':kind==='changed'?'Kedua sisi tetap mendekati dua, sedangkan nilai fungsi di masukan satu adalah empat. Mengubah satu titik tidak mengubah perilaku di sekitarnya.':'Dari kiri keluaran selalu satu; dari kanan keluaran selalu tiga. Karena kedua sisi berbeda, limit dua sisi tidak ada, meskipun nilai fungsi di titik adalah tiga.';$('#limit-plot').setAttribute('aria-label',`Grafik ${kind==='smooth'?'garis biasa':kind==='hole'?'garis dengan lubang':kind==='changed'?'garis dengan nilai titik diubah':'fungsi dengan lompatan'}. Jarak masukan dari satu ${d}. Dari kiri: masukan ${t.leftX.toFixed(3)}, keluaran ${t.leftY.toFixed(3)}. Dari kanan: masukan ${t.rightX.toFixed(3)}, keluaran ${t.rightY.toFixed(3)}. Nilai di titik ${t.at===null?'tidak terdefinisi':t.at}. Limit kiri ${t.leftLimit}, limit kanan ${t.rightLimit}. Limit dua sisi ${t.limit===null?'tidak ada':t.limit}.`);}
$('#limit-kind').addEventListener('input',draw);$('#limit-step').addEventListener('input',draw);draw();
const questions=[{tex:String.raw`\lim_{x\to1}(x+2)`,prompt:'Berapa nilai limit ini?',n:3,d:1,hint:'Perhatikan keluaran ketika masukan mendekati satu dari kedua sisi.',why:'Keluaran x ditambah dua mendekati tiga dari kiri maupun kanan.'},{tex:String.raw`\lim_{x\to1}\frac{x^2-1}{x-1}`,prompt:'Berapa nilai limit ini?',n:2,d:1,hint:'Faktorkan x kuadrat dikurangi satu, lalu sederhanakan untuk x bukan satu.',why:'Untuk x bukan satu, pecahan sama dengan x ditambah satu. Nilainya mendekati dua ketika x mendekati satu.'},{tex:String.raw`h(x)=\begin{cases}x+1,&x\ne1,\\4,&x=1,\end{cases}`,prompt:'Berapa limit h ketika masukan mendekati satu?',n:2,d:1,hint:'Nilai tepat di titik tidak menentukan perilaku di sekitarnya.',why:'Di sekitar satu, fungsi sama dengan x ditambah satu. Kedua arah mendekati dua, walaupun nilai di titik adalah empat.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis nilai limit sebagai bilangan, misalnya 2 atau 3.':'Belum tepat. Periksa perilaku dari kiri dan kanan, bukan hanya nilai tepat di titik.');}));
const choices=[{tex:String.raw`\lim_{x\to1^-}f(x)=1,\quad\lim_{x\to1^+}f(x)=3`,prompt:'Apa kesimpulan tentang limit dua sisi?',options:[{text:'Limitnya dua, rata-rata dari kedua sisi.'},{text:'Limit dua sisi tidak ada karena kedua arah berbeda.'},{text:'Limitnya selalu sama dengan nilai fungsi di titik.'}],answer:1,why:'Limit dua sisi memerlukan kedua limit satu sisi sama. Merata-ratakan dua hasil tidak menghasilkan limit dua sisi.'},{tex:String.raw`g(x)=\frac{x^2-1}{x-1}`,prompt:'Pernyataan mana yang benar di masukan satu?',options:[{text:'Nilai fungsi tidak terdefinisi, tetapi limitnya dua.'},{text:'Nilai fungsi dan limitnya sama-sama nol.'},{text:'Jika fungsi tidak terdefinisi, limit pasti tidak ada.'}],answer:0,why:'Pembagi nol membuat nilai fungsi tidak terdefinisi. Namun keluaran di sekitar titik mendekati dua dari kedua sisi.'},{tex:String.raw`f(x)=3`,prompt:'Apa limit fungsi ini ketika masukan mendekati satu?',options:[{text:'Tidak ada, karena keluaran sudah sama dengan tiga.'},{text:'Satu, mengikuti titik yang didekati masukan.'},{text:'Tiga; keluaran boleh sama dengan nilai limit.'}],answer:2,why:'Fungsi konstan selalu bernilai tiga, sehingga keluarannya sedekat apa pun dengan tiga. Limit tidak mensyaratkan keluaran berbeda dari nilai yang didekati.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-limit-idea-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-limit-idea-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();